// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /Fe:aim_test.exe
//
// Exported surface:
//   bool  WorldToScreen(const Vec3& world, const ViewMatrix& vm,
//                        int sw, int sh, Vec2& out)
//     -- projects a world-space point to viewport pixels; returns false if
//        the point is behind the camera.
//
//   Vec2  SmoothDelta(const Vec2& current, const Vec2& target,
//                      float smooth, float dt)
//     -- returns a per-frame crosshair delta that moves `current` toward
//        `target` with exponential smoothing.  `smooth` in (0,1]: 1 = instant.
//
//   bool  AimAt(const Vec3& head, const ViewMatrix& vm,
//                int sw, int sh, float smooth, float dt,
//                Vec2& delta)
//     -- projects `head`, checks the 240 px cone, fills `delta` if inside.
//        Returns false when the target is off-screen or outside the cone.

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <algorithm>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 {
    float x, y;
    Vec2() : x(0.f), y(0.f) {}
    Vec2(float x, float y) : x(x), y(y) {}
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator*(float s)        const { return {x * s,   y * s};   }
    float length() const { return std::sqrtf(x * x + y * y); }
};

struct Vec3 {
    float x, y, z;
    Vec3() : x(0.f), y(0.f), z(0.f) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}
};

// Row-major 4x4 view-projection matrix (layout matches DirectX / D3D games).
// vm[row][col]
struct ViewMatrix {
    float m[4][4];
};

// ---------------------------------------------------------------------------
// WorldToScreen
//   Multiplies `world` by the view-projection matrix and performs the
//   perspective divide.  Viewport origin is top-left.
// ---------------------------------------------------------------------------
bool WorldToScreen(const Vec3& world,
                   const ViewMatrix& vm,
                   int screenW, int screenH,
                   Vec2& out)
{
    // Clip-space transform (w-component carries the perspective divisor).
    float clipX = world.x * vm.m[0][0] + world.y * vm.m[1][0]
                + world.z * vm.m[2][0] + vm.m[3][0];
    float clipY = world.x * vm.m[0][1] + world.y * vm.m[1][1]
                + world.z * vm.m[2][1] + vm.m[3][1];
    float clipW = world.x * vm.m[0][3] + world.y * vm.m[1][3]
                + world.z * vm.m[2][3] + vm.m[3][3];

    // Behind the camera – do not project.
    if (clipW <= 0.0001f)
        return false;

    float ndcX =  clipX / clipW;   // [-1, 1]
    float ndcY =  clipY / clipW;   // [-1, 1]

    // Map NDC to viewport pixels (top-left origin).
    out.x = ( ndcX + 1.f) * 0.5f * static_cast<float>(screenW);
    out.y = (-ndcY + 1.f) * 0.5f * static_cast<float>(screenH);
    return true;
}

// ---------------------------------------------------------------------------
// SmoothDelta
//   Exponential-decay smoothing.
//   `smooth` = 1 → instant snap; approaching 0 → very slow tracking.
//   `dt`     = frame time in seconds (keeps speed frame-rate independent).
// ---------------------------------------------------------------------------
Vec2 SmoothDelta(const Vec2& current,
                 const Vec2& target,
                 float smooth,
                 float dt)
{
    // Clamp to a sane range to avoid NaN / infinite acceleration.
    smooth = std::max(0.001f, std::min(1.f, smooth));
    dt     = std::max(0.f,    std::min(1.f, dt));

    // Per-frame factor derived from a constant half-life so that behaviour
    // is independent of frame rate:  factor = 1 - exp(-smooth * dt * k)
    // For simple usage callers can pass smooth directly as a lerp alpha.
    float factor = 1.f - std::expf(-smooth * dt * 60.f);  // tuned to 60 Hz ref

    Vec2 diff = target - current;
    return diff * factor;   // the caller adds this to the cursor position
}

// ---------------------------------------------------------------------------
// AimAt
//   End-to-end helper used by the client each frame:
//     1. Project the entity head position to screen space.
//     2. Compute the vector from screen centre to the projected point.
//     3. Reject if the magnitude exceeds CONE_RADIUS_PX (240 px).
//     4. Return a smoothed crosshair delta.
// ---------------------------------------------------------------------------
static constexpr float CONE_RADIUS_PX = 240.f;

bool AimAt(const Vec3& head,
           const ViewMatrix& vm,
           int screenW, int screenH,
           float smooth,
           float dt,
           Vec2& delta)
{
    Vec2 screenPos;
    if (!WorldToScreen(head, vm, screenW, screenH, screenPos))
        return false;

    Vec2 centre(static_cast<float>(screenW) * 0.5f,
                static_cast<float>(screenH) * 0.5f);

    Vec2 toTarget = screenPos - centre;

    // Outside the 240 px cone – skip.
    if (toTarget.length() > CONE_RADIUS_PX)
        return false;

    delta = SmoothDelta(centre, screenPos, smooth, dt);
    return true;
}

// ---------------------------------------------------------------------------
// Standalone smoke test
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    // Identity view-projection (NDC == world for unit positions inside [-1,1]).
    ViewMatrix vm{};
    vm.m[0][0] = 1.f;
    vm.m[1][1] = 1.f;
    vm.m[2][2] = 1.f;
    vm.m[3][3] = 1.f;

    const int W = 1920, H = 1080;

    // --- WorldToScreen ---
    Vec2 s;
    // Origin should land exactly at screen centre.
    bool ok = WorldToScreen(Vec3(0.f, 0.f, 0.f), vm, W, H, s);
    std::printf("WorldToScreen origin: ok=%d  (%.1f, %.1f)  expected (960.0, 540.0)\n",
                ok, s.x, s.y);

    // Behind camera (w <= 0).
    ok = WorldToScreen(Vec3(0.f, 0.f, -1.f), vm, W, H, s);
    std::printf("WorldToScreen behind: ok=%d  expected 0\n", ok);

    // --- SmoothDelta ---
    Vec2 current(960.f, 540.f);
    Vec2 target (960.f, 440.f);   // 100 px above centre
    Vec2 d = SmoothDelta(current, target, 0.1f, 1.f / 60.f);
    std::printf("SmoothDelta (100 px up, smooth=0.1): dy=%.4f  expected ~negative small\n", d.y);

    // --- AimAt inside cone ---
    // A head 50 px above centre in NDC.
    float ndcOffY = 50.f / (H * 0.5f);  // convert px offset to NDC
    Vec3 headInCone(0.f, ndcOffY, 0.f);
    Vec2 delta;
    ok = AimAt(headInCone, vm, W, H, 0.5f, 1.f / 60.f, delta);
    std::printf("AimAt inside cone: ok=%d  delta=(%.4f, %.4f)\n", ok, delta.x, delta.y);

    // A head 300 px to the right (outside 240 px cone).
    float ndcOffX = 300.f / (W * 0.5f);
    Vec3 headOutside(ndcOffX, 0.f, 0.f);
    ok = AimAt(headOutside, vm, W, H, 0.5f, 1.f / 60.f, delta);
    std::printf("AimAt outside cone: ok=%d  expected 0\n", ok);

    return 0;
}
#endif // AIM_SMOKE
